param([ValidateSet('x86','x64')][string]$Platform)
$ErrorActionPreference='Stop'
if (!$Platform) {
  foreach ($arch in @('x86','x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -Platform $arch
    if ($LASTEXITCODE -ne 0) { throw "External ReShade input compilation failed for $arch" }
  }
  $repoRoot=Split-Path $PSScriptRoot -Parent
  foreach ($clientArch in @('x86','x64')) { foreach ($hostArch in @('x86','x64')) {
    & "$repoRoot/.deps/reshade-input-$clientArch/process-test.exe" "$repoRoot/.deps/reshade-input-$hostArch/process-test.exe"
    if ($LASTEXITCODE -ne 0) { throw "Cross-process External ReShade input failed: $clientArch -> $hostArch" }
  } }
  exit 0
}
$repoRoot=Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot 'assert_native_architecture.ps1')
$source=Join-Path $repoRoot '.deps/dxvk-remix'
. (Join-Path $source 'bridge/build_common.ps1')
SetupVS -Platform $Platform -VcVarsVer '14.29'
$testDir=Join-Path $repoRoot ".deps/reshade-input-$Platform"
New-Item -ItemType Directory -Force $testDir | Out-Null
Push-Location $testDir
try {
  & python.exe "$repoRoot/scripts/generate_reshade_input_fixture.py" --source "$repoRoot/.deps/reshade" --out $testDir
  if ($LASTEXITCODE -ne 0) { throw 'Actual ReShade extraction failed' }
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX "/I$repoRoot/experiments/reshade-input" "$repoRoot/tests/reshade_input_wire.cpp" /Fe:wire-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Input wire compilation failed' }
  Assert-NativeArchitecture -Path (Join-Path $testDir 'wire-test.exe') -Architecture $Platform
  & .\wire-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Input wire test failed' }
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX "/I$repoRoot/tests/reshade-input-fixture" "/I$testDir" "$repoRoot/tests/reshade_input_native.cpp" /Fe:native-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Native ReShade-method fixture compilation failed' }
  Assert-NativeArchitecture -Path (Join-Path $testDir 'native-test.exe') -Architecture $Platform
  & .\native-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Native ReShade-method fixture failed' }
  & python.exe "$repoRoot/scripts/generate_capture_state_fixture.py" --source $source --output "$testDir/capture-state.cpp"
  if ($LASTEXITCODE -ne 0) { throw 'Capture-state extraction failed' }
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX capture-state.cpp /Fe:capture-state.exe
  if ($LASTEXITCODE -ne 0) { throw 'Capture-state fixture compilation failed' }
  Assert-NativeArchitecture -Path (Join-Path $testDir 'capture-state.exe') -Architecture $Platform
  & .\capture-state.exe
  if ($LASTEXITCODE -ne 0) { throw 'Capture-state concurrency test failed' }
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX "/I$source/bridge/src/util" "/I$source/bridge/src/client" "$repoRoot/tests/reshade_input_client.cpp" /Fe:client-test.exe /link user32.lib
  if ($LASTEXITCODE -ne 0) { throw 'Actual LDB Client collector compilation failed' }
  Assert-NativeArchitecture -Path (Join-Path $testDir 'client-test.exe') -Architecture $Platform
  & .\client-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Actual LDB Client collector test failed' }
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX "/I$repoRoot/experiments/reshade-input" "$repoRoot/tests/reshade_input_process.cpp" /Fe:process-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Cross-process fixture compilation failed' }
  Assert-NativeArchitecture -Path (Join-Path $testDir 'process-test.exe') -Architecture $Platform

} finally { Pop-Location }
